(async () => { const LIMIT = 3000; const log = (...a) => console.log('%c[MK-Anime]', 'color:#4267b2;font-weight:bold', ...a); const F = async (u, ms = 25000) => { const c = new AbortController(), t = setTimeout(() => c.abort(), ms); try { const r = await fetch(u, { credentials: 'include', signal: c.signal }); return await r.text(); } catch (e) { return ''; } finally { clearTimeout(t); } }; const absolutize = (href) => { try { return new URL(href, 'https://mykadri.tv/').href; } catch (e) { return href; } }; const seenPages = new Set(); const cards = new Map(); function parseListing(doc) { doc.querySelectorAll('.post').forEach((p) => { const img = p.querySelector('.post-image'); const linkEl = p.querySelector('.post-title a.post-title-primary'); if (!img || !linkEl) return; const url = absolutize(linkEl.getAttribute('href')); const titleKa = (p.querySelector('.post-title-primary') || {}).textContent?.trim() || ''; const titleEn = (p.querySelector('.post-title-secondary') || {}).textContent?.trim() || ''; const poster = img.getAttribute('src') || img.getAttribute('data-src') || ''; const year = (p.querySelector('.yearshort .left') || {}).textContent?.trim() || ''; const ratingTxt = (p.querySelector('.yearshort .right') || {}).textContent || ''; const rating = (ratingTxt.match(/[\d.]+/) || [''])[0]; const genres = [...p.querySelectorAll('.post-more .meta a[href*="/anime/"]')] .map((a) => a.textContent.trim()) .filter((t) => t && t !== 'ანიმეები ქართულად'); const directorEl = p.querySelector('.post-more .meta a[href*="rejisori"]'); const director = directorEl && directorEl.textContent.trim() !== '-' ? directorEl.textContent.trim() : ''; const description = (p.querySelector('.post-more .meta-description p') || {}).textContent?.trim() || ''; if (url && titleKa) cards.set(url, { title: titleKa, title_en: titleEn, poster, year, rating, genres, director, description }); }); } function findNextPage(doc) { const explicit = doc.querySelector('a[rel="next"], .navigation a.next, .pagination a.next'); if (explicit) return absolutize(explicit.getAttribute('href')); const byText = [...doc.querySelectorAll('a')].find((a) => /შემდეგ|next\b|»/i.test(a.textContent || '')); return byText ? absolutize(byText.getAttribute('href')) : null; } let queue = ['https://mykadri.tv/anime/']; while (queue.length && seenPages.size < LIMIT) { const url = queue.shift(); if (seenPages.has(url)) continue; seenPages.add(url); const html = await F(url); if (!html) continue; const doc = new DOMParser().parseFromString(html, 'text/html'); parseListing(doc); const next = findNextPage(doc); if (next && !seenPages.has(next)) queue.push(next); log('გვერდი დამუშავდა:', url, '| სულ ბარათი:', cards.size); } log('ჯამში ნაპოვნია', cards.size, 'ანიმეს ბარათი. ვიწყებ დეტალურ გვერდებს (embed-ისთვის)...'); const entries = [...cards.entries()]; const results = []; let done = 0; async function worker() { while (entries.length) { const [url, base] = entries.shift(); const html = await F(url); if (!html) continue; const doc = new DOMParser().parseFromString(html, 'text/html'); const iframe = doc.querySelector('iframe[data-lazy], iframe[src]'); const player = iframe ? (iframe.getAttribute('data-lazy') || iframe.getAttribute('src') || '') : ''; let ld = null; try { const ldScript = [...doc.querySelectorAll('script[type="application/ld+json"]')] .map((s) => s.textContent) .find((t) => /"@type":\s*"(Movie|TVSeries)"/.test(t || '')); if (ldScript) { const parsed = JSON.parse(ldScript); ld = (parsed['@graph'] || [parsed]).find((g) => g['@type'] === 'Movie' || g['@type'] === 'TVSeries'); } } catch (e) {} results.push({ url, title: base.title, title_en: base.title_en, poster: base.poster, year: base.year || (ld && ld.datePublished ? String(ld.datePublished).slice(0, 4) : ''), rating: base.rating || (ld && ld.aggregateRating ? ld.aggregateRating.ratingValue : ''), genre: ['ანიმე', ...base.genres].join(' / '), director: base.director, description: base.description || (ld ? ld.description : ''), player, }); if (++done % 20 === 0) log(done, '/', entries.length + done, 'დეტალური გვერდი დამუშავდა'); } } await Promise.all(Array.from({ length: 6 }, worker)); log('%cდასრულდა! ' + results.length + ' ანიმე — mykadri_anime.json ჩამოიტვირთება', 'color:#0f0;font-size:16px'); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(results)], { type: 'application/json' })); a.download = 'mykadri_anime.json'; a.click(); })();